import{_ as t,o as r,c as n,a2 as i}from"./chunks/framework.CdjpmwdR.js";const o="/assets/choreography.B4CU8w1K.svg",a="/assets/orchestration.wOY-XY5P.svg",P=JSON.parse('{"title":"Agent 正在改变服务间互联方式","description":"在 Provider 保持 OpenAPI 不变的前提下，Agent + Skill 可能接管一部分 Client 侧集成逻辑，让服务间调用更语义化。","frontmatter":{"category":"node/agentic","date":"2026-06-08","title":"Agent 正在改变服务间互联方式","description":"在 Provider 保持 OpenAPI 不变的前提下，Agent + Skill 可能接管一部分 Client 侧集成逻辑，让服务间调用更语义化。","tags":["node/agentic","OpenAPI","Skill","integration"],"image":"/blogs/assets/202606-agent-changes-service-interconnection/choreography.svg"},"headers":[],"relativePath":"blogs/2026/202606-agent-changes-service-interconnection.md","filePath":"blogs/2026/202606-agent-changes-service-interconnection.md"}'),l={name:"blogs/2026/202606-agent-changes-service-interconnection.md"};function s(c,e,g,p,h,A){return r(),n("div",null,[...e[0]||(e[0]=[i('<p>在实现了 multica + brains 的共生系统后，我开始反过来想一个问题：Agent 应用之间到底该怎么调用。它们自己已经有 Agent 模块，能调用 Agent 能力；但与此同时，我又希望它们能彼此连接，甚至被 openclaw 这类前台 Agent 统一管理。这样一来，怎么标准化调用关系，怎么限制、规划和设计大大小小的 Agent 能力边界，就成了一个问题。</p><p>过去在微服务和复杂系统里，我们其实已经有一套相对成熟的互联方式：Service Provider 暴露 OpenAPI，Service Client 负责调用，再把多个接口拼成业务流程。这套方式很有效，但它缺少业务语义，调用方往往还是要写很多定制逻辑。</p><p>如果把 API 保留给 Provider，把业务规则补进 Skill，再让 Agent 充当 Client，服务间调用也许会变成另一种样子。</p><h2 id="传统互联方式-问题不在-api-本身" tabindex="-1">传统互联方式，问题不在 API 本身 <a class="header-anchor" href="#传统互联方式-问题不在-api-本身" aria-label="Permalink to &quot;传统互联方式，问题不在 API 本身&quot;">​</a></h2><p>过去的典型模式很清楚：Service Provider 暴露 OpenAPI，Service Client 基于接口定义生成或编写调用代码，再把多个接口拼成业务流程。这套模式没有问题，它解决的是标准化调用。</p><p>但它的缺口也很明显：<strong>API 定义的是能力边界，不定义业务规则。</strong> 即使是 HATEOAS 或 GraphQL，也更擅长处理资源访问和查询表达，不太擅长直接承载这类业务规则：当订单金额小于 100 时，先查库存，再推荐一个适合“随手加一件”的商品。</p><p>这些逻辑以前当然也能做，只是往往要写很多定制代码，把多个 API、业务规则、异常处理和流程判断缝在一起。</p><h2 id="agent-让调用方开始带着业务规则工作" tabindex="-1">Agent 让调用方开始带着业务规则工作 <a class="header-anchor" href="#agent-让调用方开始带着业务规则工作" aria-label="Permalink to &quot;Agent 让调用方开始带着业务规则工作&quot;">​</a></h2><p>Agent 出现之后，我越来越觉得，应用间互联可能会多出一种新的实现方式：</p><ul><li><strong>Provider 继续暴露 API</strong></li><li><strong>Skill 补上业务规则、用户用例、多个 API 之间的业务联系，以及调用策略</strong></li><li><strong>Agent 作为调用端，加载 skill 后去理解并调用这些能力</strong></li></ul><p>也就是说，可以把它粗略理解成：</p><blockquote><p><strong>OpenAPI ≈ Skill + API</strong></p></blockquote><p>我不是想替代 OpenAPI。更像是在说：<strong>传统 OpenAPI 主要解决“能不能调”，而 Skill 补上了“在什么业务语境下怎么调”。</strong></p><p>Skill 里可以放的不只是接口说明，还可以包括：</p><ul><li>用户用例</li><li>一个或多个 API 的业务含义和联系</li><li>业务上的调用规则</li><li>技术上的异常处理策略</li></ul><p>这样一来，Service Provider 基本不需要变化，真正变化最大的其实是 Client 侧。过去要靠代码实现的大量集成逻辑，未来可能有一部分会转成 Prompt + Skill 驱动的调用和编排。</p><h2 id="两种模式-choreography-和-orchestration" tabindex="-1">两种模式：Choreography 和 Orchestration <a class="header-anchor" href="#两种模式-choreography-和-orchestration" aria-label="Permalink to &quot;两种模式：Choreography 和 Orchestration&quot;">​</a></h2><p>这件事我觉得可以分别从 Choreography 和 Orchestration 两种模式来看。</p><p><img src="'+o+'" alt="Choreography：多个 Agent Client 基于 Skill 通过 CLI/MCP 调用三个服务 API"></p><p>在 <strong>Choreography</strong> 里，没有一个中心编排者。每个应用或服务仍然像微服务一样协作，只是 Service Client 不再只是硬编码逻辑，而可以由 Agent + Skill 来承担，因此调用会更语义化、更业务化。</p><p><img src="'+a+'" alt="Orchestration：Supervisor Agent 基于 Skill 通过 CLI/MCP 编排多个服务 API"></p><p>在 <strong>Orchestration</strong> 里，我觉得更有意思：位于中心的管理者，甚至可以完全由 Agent 来实现。也就是一个 Supervisor Agent，在掌握必要上下文之后，去自主调用各个应用和服务，完成原本需要大量 Client 代码才能完成的集成流程。</p><p>说“0 代码开发”肯定是夸张了。更接近的说法是：在 Service Provider 已经提供标准 API 的前提下，<strong>Client 侧那部分定制化集成代码，可能被 Agent + Skill 大幅替代或减少。</strong></p><h2 id="我现在更倾向于这样理解它" tabindex="-1">我现在更倾向于这样理解它 <a class="header-anchor" href="#我现在更倾向于这样理解它" aria-label="Permalink to &quot;我现在更倾向于这样理解它&quot;">​</a></h2><p>这还是一个很早期的个人想法，但我现在越来越倾向于这样看：<strong>Agent 不只是给现有应用加一个智能模块，它也可能成为下一代 Service Client。</strong></p><p>如果这个方向成立，未来应用间互联要开放的，可能就不只是接口，还有能力和业务规则。</p><h2 id="needs-verification" tabindex="-1">Needs Verification <a class="header-anchor" href="#needs-verification" aria-label="Permalink to &quot;Needs Verification&quot;">​</a></h2><ul><li><code>Skill</code> 的最小可复用结构，还需要更多实践验证。</li><li>哪些 Client-side 集成逻辑适合被 Agent 替代，哪些仍然应该保留在代码里，需要更清晰的边界。</li><li>Supervisor Agent 在真实生产场景下的可靠性、审计和失败处理，还需要更多样本。</li></ul>',28)])])}const S=t(l,[["render",s]]);export{P as __pageData,S as default};
